import { describe, expect, it } from "vitest";

import { normalizeIptablesSave, probeArgv } from "./harness";

describe("normalizeIptablesSave", () => {
  it("keeps rules and user chains, drops headers, policies and counters", () => {
    expect(
      normalizeIptablesSave([
        "# Generated by iptables-save",
        "*filter",
        ":INPUT ACCEPT [0:0]",
        ":DOCKER - [0:0]",
        "-A FORWARD -j DOCKER",
        "COMMIT",
      ]),
    ).toEqual(["-A FORWARD -j DOCKER", ":DOCKER -"]);
  });

  it("ignores an empty table the kernel loaded on first use", () => {
    const before = ["*filter", "-A FORWARD -j DOCKER", "COMMIT"];
    const after = [
      ...before,
      "*raw",
      ":PREROUTING ACCEPT [12:840]",
      ":OUTPUT ACCEPT [3:180]",
      "COMMIT",
    ];
    expect(normalizeIptablesSave(after)).toEqual(normalizeIptablesSave(before));
  });

  it("still sees a rule a cell left behind", () => {
    const before = ["*filter", "-A FORWARD -j DOCKER", "COMMIT"];
    const after = [
      "*filter",
      "-A FORWARD -j DOCKER",
      "-A FORWARD -d 10.0.0.2 -j ACCEPT",
      "COMMIT",
    ];
    expect(normalizeIptablesSave(after)).not.toEqual(
      normalizeIptablesSave(before),
    );
  });
});

describe("probeArgv", () => {
  it("refuses TCP on :80 and :443 under the proxy", () => {
    expect(() => probeArgv([{ kind: "tcp", host: "h", port: 80 }])).toThrow();
    expect(() => probeArgv([{ kind: "tcp", host: "h", port: 443 }])).toThrow();
  });

  it("allows them for the no-policy control and keeps the flag off the wire", () => {
    const argv = probeArgv([
      { kind: "tcp", host: "h", port: 80, unproxied: true },
    ]);
    expect(argv[3]).toBe(
      JSON.stringify([{ kind: "tcp", host: "h", port: 80 }]),
    );
  });

  it("never puts a canary or marker in the argv in clear", () => {
    const argv = probeArgv([
      { kind: "canary_scan", canaries: ["osbit-canary-x"], namePattern: "X" },
      { kind: "https", url: "https://h/", marker: "osbit-canary-y" },
    ]);
    expect(argv.join(" ")).not.toContain("osbit-canary-");
  });
});
